-- Run on the isolated local validation database with zz.cc fixtures. Never production.
BEGIN;
DO $$
DECLARE c RECORD; r UUID; item UUID; versionid UUID; qid UUID; groupid UUID; orderid UUID; payload JSONB; alloc JSONB; result JSONB;
 buyer UUID; seller UUID; seller_two UUID; other_w UUID; other_product UUID; req UUID:=gen_random_uuid(); stock_before INTEGER; failed BOOLEAN; count_visible INTEGER; open_r UUID; open_item UUID; open_version UUID; negotiation UUID; bad JSONB;
BEGIN
 SELECT * INTO c FROM zz.cc LIMIT 1;
 SELECT owner_id INTO buyer FROM public.businesses WHERE id=c.good;
 SELECT owner_id INTO seller FROM public.businesses WHERE id=c.alpha;
 PERFORM set_config('request.jwt.claim.sub',buyer::text,true);
 payload:=jsonb_build_object('title','Enterprise integration test','deadline',now()+interval '2 days','items',jsonb_build_array(jsonb_build_object('productName','Test medicine','quantity',10,'alternativesAllowed',true)),'suppliers',jsonb_build_array(c.alpha));
 r:=public.save_enterprise_rfq(c.good,payload,req);
 IF public.save_enterprise_rfq(c.good,payload,req)<>r THEN RAISE EXCEPTION 'Draft retry duplicated RFQ'; END IF;
 failed:=false; BEGIN PERFORM public.save_enterprise_rfq(c.good,payload||'{"title":"changed"}',req); EXCEPTION WHEN OTHERS THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Mismatched retry accepted'; END IF;
 SELECT id INTO item FROM public.rfq_items WHERE rfq_id=r;
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 IF public.can_view_rfq(r) THEN RAISE EXCEPTION 'Supplier can see unpublished draft'; END IF;
 PERFORM set_config('request.jwt.claim.sub',buyer::text,true);
 PERFORM public.publish_enterprise_rfq(r,(SELECT revision FROM public.rfqs WHERE id=r));
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 IF NOT public.can_view_rfq(r) THEN RAISE EXCEPTION 'Invited supplier cannot see published RFQ'; END IF;
 PERFORM public.respond_rfq_invitation(r,c.alpha,'view');
 payload:=jsonb_build_object('validUntil',now()+interval '4 days','deliveryCharge',0,'items',jsonb_build_array(jsonb_build_object('rfqItemId',item,'productId',c.p_item_a,'quantity',10,'unitPriceGhs',12.34,'discountPercent',10,'alternative',true,'expiryDate',current_date+800)));
 versionid:=public.save_enterprise_quote(r,c.alpha,payload,true,0,gen_random_uuid());
 SELECT quote_id INTO qid FROM public.rfq_quote_versions WHERE id=versionid;
 IF (SELECT final_unit_price_ghs FROM public.rfq_quote_items WHERE rfq_quote_id=qid)<>11.11 THEN RAISE EXCEPTION 'Incorrect decimal price'; END IF;
 versionid:=public.save_enterprise_quote(r,c.alpha,payload||'{"reason":"Updated terms"}',true,1,gen_random_uuid());
 IF (SELECT count(*) FROM public.rfq_quote_versions WHERE quote_id=qid)<>2 THEN RAISE EXCEPTION 'Quote history overwritten'; END IF;
 PERFORM set_config('request.jwt.claim.sub',buyer::text,true);
 -- Exercise the actual negotiation RPC, including values that SQL NULL logic can miss.
 FOREACH bad IN ARRAY ARRAY['null'::jsonb,'[]'::jsonb,'{}'::jsonb,'{"price":null}'::jsonb,'{"price":0}'::jsonb,'{"price":{}}'::jsonb,'{"delivery":" "}'::jsonb,'{"quantity":1.5}'::jsonb,'{"price":1,"quantity":2}'::jsonb] LOOP
 failed:=false;
 BEGIN PERFORM public.rfq_negotiate(r,c.alpha,versionid,bad); EXCEPTION WHEN raise_exception THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Invalid proposal accepted: %',bad; END IF;
 END LOOP;
 FOREACH bad IN ARRAY ARRAY['{"quantity":10}'::jsonb,'{"delivery":"Tomorrow"}'::jsonb,'{"credit":"30 days"}'::jsonb,'{"substitution":"Requested brand"}'::jsonb] LOOP
 negotiation:=public.rfq_negotiate(r,c.alpha,versionid,bad);
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 PERFORM public.rfq_respond_negotiation(negotiation,'rejected','Original terms apply');
 PERFORM set_config('request.jwt.claim.sub',buyer::text,true);
 END LOOP;
 negotiation:=public.rfq_negotiate(r,c.alpha,versionid,'{"price":11.11}'::jsonb);
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 versionid:=public.save_enterprise_quote(r,c.alpha,payload||'{"reason":"Negotiation response"}',true,2,gen_random_uuid());
 PERFORM public.rfq_respond_negotiation(negotiation,'accepted','Confirmed pricing in new revision',versionid);
 IF (SELECT status FROM public.rfq_negotiations WHERE id=negotiation)<>'accepted' THEN RAISE EXCEPTION 'Negotiation response not saved'; END IF;
 IF public.rfq_document(r,versionid)->'issuer'->>'id'<>c.alpha::text THEN RAISE EXCEPTION 'Quotation issuer must be supplier'; END IF;
 PERFORM set_config('request.jwt.claim.sub',buyer::text,true);
 IF public.rfq_document(r)->'issuer'->>'id'<>c.good::text THEN RAISE EXCEPTION 'RFQ issuer must be pharmacy'; END IF;
 alloc:=jsonb_build_array(jsonb_build_object('versionId',versionid,'quoteItemId',(SELECT id FROM public.rfq_quote_items WHERE rfq_quote_id=qid),'quantity',6,'acceptAlternative',true,'category','cash_private'));
 SELECT stock INTO stock_before FROM public.products WHERE id=c.p_item_a;
 req:=gen_random_uuid(); result:=public.propose_rfq_awards(r,alloc,'cod',req); groupid:=(result->>0)::uuid;
 IF public.propose_rfq_awards(r,alloc,'cod',req)<>result THEN RAISE EXCEPTION 'Award retry duplicated allocation'; END IF;
 IF (SELECT stock FROM public.products WHERE id=c.p_item_a)<>stock_before THEN RAISE EXCEPTION 'Award proposal deducted stock'; END IF;
 failed:=false; BEGIN PERFORM public.propose_rfq_awards(r,alloc,'cod',gen_random_uuid()); EXCEPTION WHEN OTHERS THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Over-allocation allowed'; END IF;
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 result:=public.confirm_rfq_award(groupid,true);
 IF result->>'status'<>'confirmed' THEN RAISE EXCEPTION 'Order conversion failed: %',result; END IF;
 orderid:=(result->>'orderId')::uuid;
 IF (SELECT total_ghs FROM public.orders WHERE id=orderid)<>66.66 THEN RAISE EXCEPTION 'Negotiated total not preserved'; END IF;
 IF (SELECT stock FROM public.products WHERE id=c.p_item_a)<>stock_before-6 THEN RAISE EXCEPTION 'Incorrect stock deduction'; END IF;
 IF public.confirm_rfq_award(groupid,true)->>'orderId'<>orderid::text THEN RAISE EXCEPTION 'Confirmation retry duplicated order'; END IF;
 IF (SELECT stock FROM public.products WHERE id=c.p_item_a)<>stock_before-6 THEN RAISE EXCEPTION 'Retry deducted twice'; END IF;
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000007',true);
 SET LOCAL ROLE authenticated;
 SELECT count(*) INTO count_visible FROM public.rfq_quote_versions WHERE rfq_id=r;
 RESET ROLE;
 IF count_visible<>0 THEN RAISE EXCEPTION 'Competitor can read quote versions'; END IF;
 PERFORM set_config('request.jwt.claim.sub',buyer::text,true);
 -- Existing cancellation restores stock through its ordinary evidence-backed lifecycle.
 UPDATE public.orders SET status='cancelled' WHERE id=orderid;
 IF (SELECT stock FROM public.products WHERE id=c.p_item_a)<>stock_before THEN RAISE EXCEPTION 'Order cancellation failed to restore stock'; END IF;
 PERFORM public.rfq_transition(r,'cancel_remaining',(SELECT revision FROM public.rfqs WHERE id=r),'Demand no longer needed');
 PERFORM public.rfq_transition(r,'complete',(SELECT revision FROM public.rfqs WHERE id=r));
 IF (SELECT status FROM public.rfqs WHERE id=r)<>'completed' THEN RAISE EXCEPTION 'Resolved RFQ did not complete'; END IF;
 -- Open RFQs admit another approved wholesaler without exposing the first supplier's records.
 open_r:=public.save_enterprise_rfq(c.good,jsonb_build_object('title','Open RFQ visibility test','visibility','open','deadline',now()+interval '2 days','items',jsonb_build_array(jsonb_build_object('productName','Open test medicine','quantity',5,'alternativesAllowed',true,'coldChainRequired',true)),'suppliers','[]'::jsonb),gen_random_uuid());
 PERFORM public.publish_enterprise_rfq(open_r,(SELECT revision FROM public.rfqs WHERE id=open_r));
 other_w:=c.alpha; seller_two:=seller; other_product:=c.p_item_a;
 PERFORM set_config('request.jwt.claim.sub',seller_two::text,true);
 IF NOT public.can_view_rfq(open_r) OR EXISTS(SELECT 1 FROM public.rfq_invitees WHERE rfq_id=open_r AND wholesaler_id=other_w) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.list_enterprise_rfqs(other_w)->'rows') x WHERE x->>'id'=open_r::text) THEN RAISE EXCEPTION 'Approved non-invited supplier cannot see public open RFQ'; END IF;
 PERFORM public.respond_rfq_invitation(open_r,other_w,'view');
 SELECT id INTO open_item FROM public.rfq_items WHERE rfq_id=open_r;
 failed:=false; BEGIN PERFORM public.save_enterprise_quote(open_r,other_w,jsonb_build_object('validUntil',now()+interval '2 days','items',jsonb_build_array(jsonb_build_object('rfqItemId',open_item,'productId',other_product,'quantity',5,'unitPriceGhs',2.50,'alternative',true,'expiryDate',current_date+800))),true,0,gen_random_uuid()); EXCEPTION WHEN OTHERS THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Cold-chain requirement accepted without supplier confirmation'; END IF;
 open_version:=public.save_enterprise_quote(open_r,other_w,jsonb_build_object('validUntil',now()+interval '2 days','items',jsonb_build_array(jsonb_build_object('rfqItemId',open_item,'productId',other_product,'quantity',5,'unitPriceGhs',2.50,'alternative',true,'expiryDate',current_date+800,'batchNumber','TEST-LOT-1','coldChainSupported',true))),true,0,gen_random_uuid());
 IF open_version IS NULL OR NOT EXISTS(SELECT 1 FROM public.rfq_invitees WHERE rfq_id=open_r AND wholesaler_id=other_w AND response_status='submitted') THEN RAISE EXCEPTION 'Open RFQ supplier response was not recorded'; END IF;
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000007',true);
 SET LOCAL ROLE authenticated;
 SELECT count(*) INTO count_visible FROM public.rfq_invitees WHERE rfq_id=open_r;
 IF count_visible<>0 THEN RAISE EXCEPTION 'Open RFQ leaked participant identities'; END IF;
 SELECT count(*) INTO count_visible FROM public.rfq_quote_versions WHERE rfq_id=open_r;
 RESET ROLE;
 IF count_visible<>0 THEN RAISE EXCEPTION 'Open RFQ leaked a competing quotation'; END IF;
 PERFORM set_config('request.jwt.claim.sub',buyer::text,true);
 result:=public.rfq_procurement_report(c.good,NULL,NULL);
 IF NOT (result ? 'viewedInvitations' AND result ? 'submittedQuotesNotAwarded' AND result ? 'requestedProducts') THEN RAISE EXCEPTION 'Procurement report is missing participant metrics'; END IF;
 -- Scheduled reminders must record each eligible invitation only once.
 UPDATE public.rfqs SET response_deadline=now()+interval '12 hours' WHERE id=open_r;
 PERFORM public.run_enterprise_rfq_deadline_reminders();
 IF (SELECT count(*) FROM public.rfq_reminder_receipts WHERE rfq_id=open_r AND wholesaler_id=other_w)<>1 THEN RAISE EXCEPTION 'Scheduled reminder not recorded'; END IF;
 PERFORM public.run_enterprise_rfq_deadline_reminders();
 IF (SELECT count(*) FROM public.rfq_reminder_receipts WHERE rfq_id=open_r AND wholesaler_id=other_w)<>1 THEN RAISE EXCEPTION 'Scheduled reminder duplicated'; END IF;
 -- No broad administrative commercial access without an audited investigation.
 PERFORM set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
 SET LOCAL ROLE authenticated;
 SELECT count(*) INTO count_visible FROM public.rfq_quote_versions WHERE rfq_id=r;
 RESET ROLE;
 IF count_visible<>0 THEN RAISE EXCEPTION 'Blanket admin commercial read remains'; END IF;
 RAISE NOTICE 'PASS: drafts, private/open publication, immutable revisions, decimal pricing, allocation limits, checkout, stock, retries and competitor privacy';
END $$;
ROLLBACK;
